fn fibonacci(n: usize) -> Vec<i32> {
    // Since n is at least 2, we can safely initialize with first two Fibonacci numbers
    let mut result = vec![0, 1];
    
    // If n is exactly 2, we already have the result
    if n == 2 {
        return result;
    }
    
    // Generate remaining Fibonacci numbers
    for i in 2..n {
        let next = result[i - 1] + result[i - 2];
        result.push(next);
    }
    
    result
}